/* B"H */
#include <windows.h>
#include <gl/gl.h>
#include <stdio.h>
#include <stdint.h>

static int g_running = 1;
static int g_frames = 0;
static unsigned int g_bytecode_len = 0;
static unsigned int g_bytecode_ok = 0;

static LRESULT CALLBACK AwtsWndProc(HWND hwnd, UINT msg, WPARAM wp, LPARAM lp) {
  switch (msg) {
    case WM_CLOSE:
    case WM_DESTROY:
      g_running = 0;
      PostQuitMessage(0);
      return 0;
  }
  return DefWindowProc(hwnd, msg, wp, lp);
}

static int load_merkava_file(const char* path) {
  FILE* f = fopen(path, "rb");
  if (!f) return 0;
  unsigned char head[4] = {0,0,0,0};
  fseek(f, 0, SEEK_END);
  long size = ftell(f);
  fseek(f, 0, SEEK_SET);
  fread(head, 1, 4, f);
  fclose(f);
  g_bytecode_len = size > 0 ? (unsigned int)size : 0;
  g_bytecode_ok = (size >= 5 && head[0] == 'M' && head[1] == 'D' && head[2] == '2' && head[3] == 0);
  return g_bytecode_ok ? 1 : 0;
}

static void draw_scene(void) {
  float pulse = (float)((g_frames % 120) / 120.0f);
  glViewport(0, 0, 800, 480);
  glClearColor(0.015f, 0.02f + pulse * 0.05f, 0.04f, 1.0f);
  glClear(GL_COLOR_BUFFER_BIT);
  glBegin(GL_TRIANGLES);
    glColor3f(1.0f, 0.25f, 0.15f); glVertex2f(-0.65f, -0.55f);
    glColor3f(0.1f, 0.9f, 0.35f);  glVertex2f( 0.65f, -0.55f);
    glColor3f(0.25f, 0.45f, 1.0f); glVertex2f( 0.00f,  0.70f);
  glEnd();
}

int main(int argc, char** argv) {
  const char* bytecodePath = argc > 1 ? argv[1] : "dist/sample.merkava";
  int loaded = load_merkava_file(bytecodePath);
  printf("B'H Merkava OpenGL native browser\n");
  printf("bytecode=%s bytes=%u ok=%u\n", bytecodePath, g_bytecode_len, g_bytecode_ok);
  fflush(stdout);

  HINSTANCE hInst = GetModuleHandle(NULL);
  WNDCLASS wc;
  ZeroMemory(&wc, sizeof(wc));
  wc.style = CS_OWNDC;
  wc.lpfnWndProc = AwtsWndProc;
  wc.hInstance = hInst;
  wc.lpszClassName = "AwtsMerkavaOpenGLBrowser";
  wc.hCursor = LoadCursor(NULL, IDC_ARROW);
  if (!RegisterClass(&wc)) {
    printf("register_window_failed=%lu\n", GetLastError());
    return 10;
  }

  HWND hwnd = CreateWindowEx(
    0, wc.lpszClassName, "B'H Merkava Native OpenGL Browser",
    WS_OVERLAPPEDWINDOW | WS_VISIBLE,
    CW_USEDEFAULT, CW_USEDEFAULT, 800, 480,
    NULL, NULL, hInst, NULL
  );
  if (!hwnd) {
    printf("create_window_failed=%lu\n", GetLastError());
    return 11;
  }

  HDC dc = GetDC(hwnd);
  PIXELFORMATDESCRIPTOR pfd;
  ZeroMemory(&pfd, sizeof(pfd));
  pfd.nSize = sizeof(pfd);
  pfd.nVersion = 1;
  pfd.dwFlags = PFD_DRAW_TO_WINDOW | PFD_SUPPORT_OPENGL | PFD_DOUBLEBUFFER;
  pfd.iPixelType = PFD_TYPE_RGBA;
  pfd.cColorBits = 32;
  pfd.cDepthBits = 24;
  pfd.iLayerType = PFD_MAIN_PLANE;
  int pf = ChoosePixelFormat(dc, &pfd);
  if (!pf || !SetPixelFormat(dc, pf, &pfd)) {
    printf("pixel_format_failed=%lu\n", GetLastError());
    return 12;
  }

  HGLRC rc = wglCreateContext(dc);
  if (!rc || !wglMakeCurrent(dc, rc)) {
    printf("opengl_context_failed=%lu\n", GetLastError());
    return 13;
  }

  MSG msg;
  DWORD start = GetTickCount();
  while (g_running && GetTickCount() - start < 1800) {
    while (PeekMessage(&msg, NULL, 0, 0, PM_REMOVE)) {
      if (msg.message == WM_QUIT) g_running = 0;
      TranslateMessage(&msg);
      DispatchMessage(&msg);
    }
    draw_scene();
    SwapBuffers(dc);
    g_frames++;
    Sleep(16);
  }

  wglMakeCurrent(NULL, NULL);
  if (rc) wglDeleteContext(rc);
  ReleaseDC(hwnd, dc);
  DestroyWindow(hwnd);
  printf("frames=%d loaded=%d renderer=win32-opengl\n", g_frames, loaded);
  fflush(stdout);
  return loaded ? 0 : 2;
}
